def canonical_goal(value):
    raw = str(value or "").strip()
    if not raw:
        return ""
    normalized = " ".join(raw.casefold().replace("_", " ").replace("-", " ").split())
    return GOAL_ALIASES.get(normalized, normalized.replace(" ", "_"))


def normalize_goal_catalog(apps, schema_editor):
    database = schema_editor.connection.alias
    ExerciseGoal = apps.get_model("account", "ExerciseGoal")
    AthleteTrainingProfile = apps.get_model("account", "AthleteTrainingProfile")
    goal_models = (
        apps.get_model("account", "ExerciseSetType"),
        apps.get_model("account", "ExerciseRepetitionType"),
        apps.get_model("account", "ExerciseRestType"),
    )

    for model in goal_models:
        for value in model.objects.using(database).values_list("goal", flat=True).distinct():
            normalized = canonical_goal(value)
            if normalized != value:
                model.objects.using(database).filter(goal=value).update(goal=normalized)

    for profile in AthleteTrainingProfile.objects.using(database).all().only("pk", "primary_goal").iterator():
        normalized = canonical_goal(profile.primary_goal)
        if normalized != profile.primary_goal:
            AthleteTrainingProfile.objects.using(database).filter(pk=profile.pk).update(primary_goal=normalized)

    winners = {}
    duplicates = []
    for goal in ExerciseGoal.objects.using(database).order_by("pk").all():
        key = canonical_goal(goal.name_en)
        if not key:
            duplicates.append(goal.pk)
            continue
        current = winners.get(key)
        is_exact = (goal.name_en or "").strip().casefold() == key
        current_is_exact = current and (current.name_en or "").strip().casefold() == key
        if current is None or (is_exact and not current_is_exact):
            if current is not None:
                duplicates.append(current.pk)
            winners[key] = goal
        else:
            duplicates.append(goal.pk)

    if duplicates:
        ExerciseGoal.objects.using(database).filter(pk__in=duplicates).delete()
    for key, goal in winners.items():
        if goal.name_en != key:
            ExerciseGoal.objects.using(database).filter(pk=goal.pk).update(name_en=key)


